import json
import os
from taf.sbts.oam.coam.admin import admin
from taf.rfrl.utilities.robot.general import is_dry_run

COMMANDS_RESPONSE_DIR = os.path.join(os.path.dirname(__file__), 'commands_response')


class CommandHandler(object):
    def __init__(self):
        self.bts_host = '192.168.255.1'
        self.admin = admin()
        self.admin_conn = None if is_dry_run() else self.admin.connect_to(self.bts_host)

    def teardown_admin(self):
        if not is_dry_run():
            self.admin.teardown()

    def initialize_all_commands(self, commands_list):
        self.get_all_comands_output(commands_list=commands_list, initialize=True)

    def get_all_comands_output(self, commands_list, initialize=False):
        for command in commands_list:
            self.get_command_output(command, initialize)

    def get_command_output(self, command, initialize=False):
        """
        Method is getting response from AdminCLI command.
        :param str command: AdminCLI command name
        :param bool initialize: Information how the file with response should be named
        :return: json AdminCLI response
        """
        command_response = getattr(self.admin, command)()
        resp = json.dumps(command_response, indent=4)
        if initialize:
            self.write_output_to_file(command=command, command_output=resp)
        else:
            self.write_output_to_file(command, command_output=resp, suffix='_current')
        return resp

    @staticmethod
    def write_output_to_file(command, command_output, suffix=''):
        with open(os.path.join(COMMANDS_RESPONSE_DIR, command + suffix), 'w+') as f:
            f.write(command_output)

    def read_all_outputs_from_file(self, commands_list):

        outputs = []
        for command in commands_list:
            pattern, current = self.read_outputs_from_file(command)
            outputs.append({
                command: {'pattern': pattern,
                          'current': current}
            })
        return outputs

    @staticmethod
    def read_outputs_from_file(command):
        """
        Methos is getting outputs from file with AdminCLI command responses for current state and pattern.
        :param str command: AdminCLI command name
        :return: json AdminCLI command response (pattern and current state)
        """
        with open(os.path.join(COMMANDS_RESPONSE_DIR, command), 'r') as p:
            pattern = json.loads(p.read())
        with open(os.path.join(COMMANDS_RESPONSE_DIR, command + '_current'), 'r') as c:
            current = json.loads(c.read())
        return pattern, current

